+    rec.put("decfield", getNonzeroEncodedBigDecimal(rand, 6, 10));
+    rec.put("lowprecision", getNonzeroEncodedBigDecimal(rand, 2, 4));
+    rec.put("highprecision", getNonzeroEncodedBigDecimal(rand, 12, 32));
